// Local file readers. No inference of physical dimensions from photographs.
export function numberValue(raw){let s=String(raw).trim().replace(/\s/g,'');if(/^\d{1,3}[.,]\d{3}$/.test(s))return null;if(s.includes(',')&&s.includes('.')){if(s.lastIndexOf(',')>s.lastIndexOf('.'))s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'')}else s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)&&n>=0?n:null}
export function textRows(text,source='Texto',page=1){const rows=[],seen=new Set();for(const line of text.split('\n')){const l=line.trim();if(!l)continue;const re=/(\d+(?:[ .,]\d+)*(?:[.,]\d+)?)\s*(mm|cm|m²|m2|m³|m3|metros|metro|kg|un\b|m\b)/gi;let m;while((m=re.exec(l))){const n=numberValue(m[1]);if(n===null)continue;const rawUnit=m[2].toLowerCase(),factor=rawUnit==='mm'?0.001:rawUnit==='cm'?0.01:1,unit=['mm','cm','metro','metros'].includes(rawUnit)?'m':rawUnit==='m2'?'m²':rawUnit==='m3'?'m³':rawUnit;const key=page+'|'+l+'|'+m.index;if(seen.has(key))continue;seen.add(key);const before=l.slice(0,m.index).toLowerCase();const target=/largura\s*[:=]?\s*$/.test(before)?'width':/altura\s*[:=]?\s*$/.test(before)?'height':null;rows.push({kind:'dimension',label:l.slice(0,120),value:Math.round(n*factor*1e9)/1e9,unit,source:`${source} · p. ${page} · «${m[0]}»`,evidence:l,page,target,rawValue:m[0]})}const material=l.match(/(?:material\s*[:=]?\s*)?(aço(?:\s+inoxidável)?|aco(?:\s+inoxidavel)?|inox(?:\s+\d{3})?|alum[ií]nio|ferro)\b/i);if(material)rows.push({kind:'material',label:'Material indicado no texto',value:material[1],unit:'',source:`${source} · p. ${page}`,evidence:l,page,target:'material'})}return rows}
export const DXF_UNITS={1:{factor:.0254,label:'polegadas'},2:{factor:.3048,label:'pés'},4:{factor:.001,label:'mm'},5:{factor:.01,label:'cm'},6:{factor:1,label:'m'},7:{factor:1000,label:'km'},9:{factor:.0000254,label:'mil'},10:{factor:.9144,label:'jardas'},13:{factor:.000001,label:'µm'}};
const distance=(a,b)=>Math.hypot(b.x-a.x,b.y-a.y,(b.z||0)-(a.z||0));
export function polyMetrics(vertices,closed=false){let length=0,area=0;const paths=[];for(let i=0;i<vertices.length-(closed?0:1);i++){const a=vertices[i],b=vertices[(i+1)%vertices.length],chord=distance(a,b),bulge=Number(a.bulge)||0;let segment=chord;area+=(a.x*b.y-b.x*a.y)/2;if(bulge&&chord){const theta=4*Math.atan(bulge),radius=chord*(1+bulge*bulge)/(4*Math.abs(bulge));segment=radius*Math.abs(theta);area+=radius*radius*(theta-Math.sin(theta))/2;const dx=b.x-a.x,dy=b.y-a.y,offset=chord*(1-bulge*bulge)/(4*bulge),cx=(a.x+b.x)/2-dy/chord*offset,cy=(a.y+b.y)/2+dx/chord*offset,start=Math.atan2(a.y-cy,a.x-cx),steps=Math.max(8,Math.ceil(Math.abs(theta)*12));for(let j=0;j<steps;j++){const t=start+theta*j/steps;paths.push({x:cx+radius*Math.cos(t),y:cy+radius*Math.sin(t)})}}else paths.push({x:a.x,y:a.y});length+=segment}if(vertices.length)paths.push(closed?vertices[0]:vertices.at(-1));return{length,area:closed?Math.abs(area):null,points:paths}}
export function readDXF(text,Parser,override=null){if(text.startsWith('AutoCAD Binary DXF'))throw Error('DXF binário não suportado. Exporta um DXF ASCII.');if(text.length>20e6)throw Error('DXF acima do limite de 20 MB.');const doc=new Parser().parseSync(text);if(!doc?.entities)throw Error('Não foi possível ler as entidades deste DXF.');const declared=doc.header?.$INSUNITS,units=override?DXF_UNITS[Number(override)]:DXF_UNITS[declared];const result={kind:'DXF',rows:[],notes:[],rawText:'',shapes:[],stats:{entities:doc.entities.length,units:units?.label||'Não declaradas',schema:'DXF ASCII'},needsUnits:!units,unitCode:override||declared||0};if(!units){result.notes.push('O ficheiro não declara uma unidade suportada em $INSUNITS. Escolhe a unidade de desenho antes de calcular.');return result}if(override)result.notes.push('Unidade definida manualmente: '+units.label+'. Confirma com o autor do desenho.');const factor=units.factor,ignored={},texts=[];let has3D=false;const push=(e,label,value,unit,idx)=>{if(Number.isFinite(value)&&value>=0)result.rows.push({kind:'geometry',label,value:Math.round(value*1e8)/1e8,unit,source:`DXF · ${e.type} #${e.handle||idx+1} · layer ${e.layer||'0'}`,evidence:`Geometria do ficheiro; unidade ${units.label}${override?' (manual)':''}. Não identifica automaticamente materiais.`,layer:e.layer||'0',entity:e.type,handle:String(e.handle||idx+1)})};for(let i=0;i<Math.min(doc.entities.length,20000);i++){const e=doc.entities[i];if(e.inPaperSpace){ignored['Paper space']=(ignored['Paper space']||0)+1;continue}const tilted=Math.abs(e.extrusionDirectionX||e.extrusionDirection?.x||0)>1e-8||Math.abs(e.extrusionDirectionY||e.extrusionDirection?.y||0)>1e-8||(e.extrusionDirectionZ!==undefined&&e.extrusionDirectionZ!==1);if(tilted){ignored[e.type+' (plano não XY)']=(ignored[e.type+' (plano não XY)']||0)+1;continue}const layer=e.layer||'0';if(e.type==='LINE'&&e.vertices?.length>=2){const[a,b]=e.vertices;push(e,'Comprimento de linha',distance(a,b)*factor,'m',i);result.shapes.push({points:[a,b],layer});if((a.z||0)!==(b.z||0))has3D=true}else if(['LWPOLYLINE','POLYLINE'].includes(e.type)&&e.vertices?.length){if(e.is3dPolygonMesh||e.isPolyfaceMesh||e.is3dPolyline||e.includesCurveFitVertices||e.includesSplineFitVertices){ignored[e.type+' 3D/malha']=(ignored[e.type+' 3D/malha']||0)+1;continue}const m=polyMetrics(e.vertices,e.shape);push(e,e.shape?'Perímetro de contorno fechado':'Comprimento de polilinha',m.length*factor,'m',i);if(e.shape)push(e,'Área geométrica do contorno',m.area*factor*factor,'m²',i);result.shapes.push({points:m.points,layer,closed:!!e.shape})}else if(['CIRCLE','ARC'].includes(e.type)&&e.center&&e.radius>0){const full=e.type==='CIRCLE',start=full?0:e.startAngle,span=full?Math.PI*2:((e.endAngle-e.startAngle)%(Math.PI*2)+Math.PI*2)%(Math.PI*2);push(e,full?'Circunferência':'Comprimento de arco',e.radius*span*factor,'m',i);if(full){push(e,'Área do círculo',Math.PI*e.radius*e.radius*factor*factor,'m²',i);push(e,'Diâmetro',2*e.radius*factor,'m',i)}const pts=[];for(let j=0;j<=64;j++){const a=start+span*j/64;pts.push({x:e.center.x+Math.cos(a)*e.radius,y:e.center.y+Math.sin(a)*e.radius})}result.shapes.push({points:pts,layer,closed:full})}else if(['TEXT','MTEXT','ATTRIB','ATTDEF'].includes(e.type)){texts.push(String(e.text||'').replace(/\\P/g,'\n').replace(/\\[A-Za-z][^;]*;/g,''))}else{ignored[e.type]=(ignored[e.type]||0)+1}}
if(doc.entities.length>20000)result.notes.push('Limite atingido: apenas as primeiras 20 000 entidades foram examinadas.');if(Object.keys(ignored).length)result.notes.push('Entidades não medidas: '+Object.entries(ignored).map(([t,n])=>`${n} × ${t}`).join(', ')+'. Blocos INSERT, cotas DIMENSION, splines e hachuras não são expandidos.');if(has3D)result.notes.push('Há linhas 3D: o comprimento usa XYZ; a pré-visualização é uma projeção XY.');result.rawText=texts.join('\n');result.rows.push(...textRows(result.rawText,'Texto DXF'));result.stats.measured=result.rows.length;result.stats.layers=[...new Set(doc.entities.map(e=>e.layer||'0'))].length;result.notes.push('Comprimentos e áreas são geométricos, não listas de material. Contornos sobrepostos, furos, espessuras, perdas e processos não são descontados nem inferidos.');if(result.rows.length>2000){result.rows=result.rows.slice(0,2000);result.notes.push('Resultados limitados a 2 000 medições. Divide o desenho para analisar o restante.')}result.shapes=result.shapes.slice(0,3000);return result}
const val=x=>x&&typeof x==='object'&&'value'in x?x.value:x;
export async function readIFC(bytes,W,progress=()=>{}){const api=new W.IfcAPI();api.SetWasmPath('/vendor/ifc/',true);await api.Init(undefined,true);api.SetLogLevel?.(W.LogLevel?.LOG_LEVEL_OFF??6);const model=api.OpenModel(bytes,{COORDINATE_TO_ORIGIN:true});if(model<0)throw Error('Não foi possível abrir este IFC. Exporta IFC2x3 ou IFC4 em formato .ifc.');const result={kind:'IFC',rows:[],notes:[],elements:[],rawText:'',stats:{schema:api.GetModelSchema(model)}};const cache=new Map();const get=x=>{const id=typeof x==='number'?x:val(x);if(!Number.isInteger(id))return null;if(!cache.has(id))cache.set(id,api.GetLine(model,id,false));return cache.get(id)};const ids=type=>{const v=api.GetLineIDsWithType(model,typeof type==='string'?W[type]:type);return Array.from({length:v.size()},(_,i)=>v.get(i))};const typename=l=>api.GetNameFromTypeCode(l.type).toUpperCase();const prefixes={EXA:1e18,PETA:1e15,TERA:1e12,GIGA:1e9,MEGA:1e6,KILO:1000,HECTO:100,DECA:10,DECI:.1,CENTI:.01,MILLI:.001,MICRO:1e-6,NANO:1e-9,PICO:1e-12,FEMTO:1e-15,ATTO:1e-18};function unitInfo(ref,depth=0){if(!ref||depth>5)return null;const u=get(ref);if(!u)return null;const type=typename(u),kind=val(u.UnitType);if(type==='IFCSIUNIT'){const prefix=val(u.Prefix),f=prefix?(prefixes[prefix]??NaN):1,name=val(u.Name);if(name==='METRE')return{kind,unit:'m',factor:f};if(name==='SQUARE_METRE')return{kind,unit:'m²',factor:f*f};if(name==='CUBIC_METRE')return{kind,unit:'m³',factor:f*f*f};if(name==='GRAM')return{kind,unit:'kg',factor:f/1000};if(name==='SECOND')return{kind,unit:'h',factor:f/3600}}if(type==='IFCCONVERSIONBASEDUNIT'){const c=get(u.ConversionFactor),base=unitInfo(c?.UnitComponent,depth+1),n=Number(val(c?.ValueComponent));if(base&&Number.isFinite(n))return{...base,kind,factor:base.factor*n}}return null}
try{const project=get(ids('IFCPROJECT')[0]);const unitSet=get(project?.UnitsInContext),units={};for(const u of unitSet?.Units||[]){const info=unitInfo(u);if(info)units[info.kind]=info}result.stats.units=units.LENGTHUNIT?.unit||'Unidade de comprimento desconhecida';const psets=new Map(),mats=new Map();for(const id of ids('IFCRELDEFINESBYPROPERTIES')){const r=get(id);for(const ref of r.RelatedObjects||[]){const key=val(ref);if(!psets.has(key))psets.set(key,[]);psets.get(key).push(r.RelatingPropertyDefinition)}}for(const id of ids('IFCRELASSOCIATESMATERIAL')){const r=get(id);for(const ref of r.RelatedObjects||[])mats.set(val(ref),r.RelatingMaterial)}
function materialNames(ref,depth=0,seen=new Set()){if(!ref||depth>8)return[];const id=val(ref);if(seen.has(id))return[];seen.add(id);const m=get(ref);if(!m)return[];if(typename(m)==='IFCMATERIAL')return[val(m.Name)||'Material sem nome'];let names=[];for(const k of ['Material','Materials','ForLayerSet','MaterialLayers','ForProfileSet','MaterialProfiles','MaterialConstituents']){const v=m[k];if(v)for(const r of Array.isArray(v)?v:[v])names.push(...materialNames(r,depth+1,seen))}return[...new Set(names)]}
const all=api.GetAllLines(model),elements=[];for(let i=0;i<all.size();i++){const id=all.get(i),type=api.GetLineType(model,id);if(api.IsIfcElement(type))elements.push(id)}result.stats.entities=elements.length;const max=500;if(elements.length>max)result.notes.push(`Modelo com ${elements.length} elementos. Apenas os primeiros ${max} são detalhados nesta versão; divide o modelo por especialidade.`);
for(let i=0;i<Math.min(max,elements.length);i++){if(i%20===0)progress({status:'A ler elementos IFC',progress:i/Math.min(max,elements.length)});const id=elements[i],el=get(id),type=typename(el),name=String(val(el.Name)||type),globalId=String(val(el.GlobalId)||''),materials=materialNames(mats.get(id)).join(', '),source=`IFC · #${id} · ${type} · ${globalId}`;result.elements.push({id,type,name,globalId,materials});const add=(label,value,unit,evidence,kind='quantity')=>{if(Number.isFinite(value)&&value>=0)result.rows.push({kind,label:`${name} · ${label}`,value,unit,source,evidence,elementId:id,elementType:type,material:materials})};add('Contagem do elemento',1,'un','Um elemento do modelo. Pode coexistir com as suas medições; não somar como se fossem peças adicionais.');for(const [field,label]of[['OverallWidth','Largura declarada'],['OverallHeight','Altura declarada']]){const n=Number(val(el[field])),u=units.LENGTHUNIT;if(el[field]!=null&&u)add(label,n*u.factor,u.unit,field+' do elemento; unidade do projeto.','dimension')}
const visit=(ref,path,depth=0)=>{if(depth>5)return;const q=get(ref);if(!q)return;const qtype=typename(q),qname=String(val(q.Name)||qtype),prefix=path?path+' / '+qname:qname;if(qtype==='IFCELEMENTQUANTITY'||qtype==='IFCPHYSICALCOMPLEXQUANTITY'){for(const child of q.Quantities||q.HasQuantities||[])visit(child,prefix,depth+1);return}const mapping={IFCQUANTITYLENGTH:['LengthValue','LENGTHUNIT'],IFCQUANTITYAREA:['AreaValue','AREAUNIT'],IFCQUANTITYVOLUME:['VolumeValue','VOLUMEUNIT'],IFCQUANTITYWEIGHT:['WeightValue','MASSUNIT'],IFCQUANTITYTIME:['TimeValue','TIMEUNIT'],IFCQUANTITYCOUNT:['CountValue','COUNT']};const map=mapping[qtype];if(map){const [field,k]=map,n=Number(val(q[field])),u=k==='COUNT'?{unit:'un',factor:1}:q.Unit?unitInfo(q.Unit):units[k];add(prefix,u?n*u.factor:n,u?.unit||'?',`Quantidade declarada #${q.expressID}: ${qtype}.${field}${u?' · unidade normalizada':' · unidade não resolvida, confirmar manualmente'}`)}};for(const set of psets.get(id)||[])visit(set,'');}
result.stats.measured=result.rows.length;result.stats.materials=result.elements.filter(e=>e.materials).length;result.notes.push('Leitura de elementos, materiais diretamente associados e quantidades declaradas. Não calcula quantidades pela geometria 3D nem herda propriedades dos tipos. A ausência de uma quantidade significa “não encontrada”, não zero.');if(!units.LENGTHUNIT)result.notes.push('Unidade de comprimento do projeto não resolvida. As dimensões diretas não foram convertidas.');if(result.rows.some(r=>r.unit==='?'))result.notes.push('Há quantidades sem unidade resolvida: escolhe a unidade e confirma o valor antes de usar.');if(result.rows.length>3000){result.rows=result.rows.slice(0,3000);result.notes.push('Resultados limitados a 3 000 registos.')}return result}finally{api.CloseModel(model)}}
